import { MakeLogicType, connect, kea, key, path, props, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { teamLogic } from 'scenes/teamLogic'

import type { IntegrationType, TeamPublicType, TeamType } from '~/types'

import type { SandboxEmailSenderProvisionResult } from '../../../../frontend/src/lib/integrations/integrationsLogic'
import { DefaultEmailSender, resolveDefaultEmailSender } from '../Channels/defaultEmailSender'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicValues {
    currentProjectId: number | string // integrationsLogic
    integrations: IntegrationType[] | null // integrationsLogic
    ownEmailIntegrations: IntegrationType[] // integrationsLogic
    sandboxEmailSender: IntegrationType | null // integrationsLogic
    sandboxEmailSenderEnabled: boolean // integrationsLogic
    sandboxEmailSenderProvisionResult: SandboxEmailSenderProvisionResult | null // integrationsLogic
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    firstRunSender: DefaultEmailSender | null
    resolvedFirstRunSender: DefaultEmailSender | null
    resolvedFirstRunSenderLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicActions {
    resolveFirstRunSender: () => any
    resolveFirstRunSenderFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    resolveFirstRunSenderSuccess: (
        resolvedFirstRunSender: DefaultEmailSender | null,
        payload?: any
    ) => {
        resolvedFirstRunSender: DefaultEmailSender | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicProps {
    allowSandbox: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicMeta {
    key: 'own' | 'sandbox'
    __keaTypeGenInternalSelectorTypes: {
        firstRunSender: (
            integrations: IntegrationType[] | null,
            ownEmailIntegrations: IntegrationType[],
            sandboxEmailSender: IntegrationType | null,
            currentTeam: TeamPublicType | TeamType | null
        ) => DefaultEmailSender | null
    }
}

export type firstRunSenderLogicType = MakeLogicType<
    firstRunSenderLogicValues,
    firstRunSenderLogicActions,
    firstRunSenderLogicProps,
    firstRunSenderLogicMeta
>

export const firstRunSenderLogic = kea<firstRunSenderLogicType>([
    props({} as { allowSandbox: boolean }),
    key((props) => (props.allowSandbox ? 'sandbox' : 'own')),
    path((key) => ['products', 'workflows', 'frontend', 'firstRun', 'firstRunSenderLogic', key]),
    connect({
        values: [
            integrationsLogic,
            [
                'integrations',
                'ownEmailIntegrations',
                'sandboxEmailSender',
                'sandboxEmailSenderEnabled',
                'sandboxEmailSenderProvisionResult',
                'currentProjectId',
            ],
            teamLogic,
            ['currentTeam'],
        ],
    }),
    selectors({
        firstRunSender: [
            (s) => [s.integrations, s.ownEmailIntegrations, s.sandboxEmailSender, s.currentTeam],
            (
                integrations: IntegrationType[] | null,
                ownSenders: IntegrationType[],
                sandbox: IntegrationType | null,
                team: TeamPublicType | TeamType | null
            ): DefaultEmailSender | null => {
                const own = resolveDefaultEmailSender(
                    integrations,
                    team && 'workflows_config' in team ? team.workflows_config?.default_email_integration_id : null
                )
                return (
                    own ??
                    (sandbox && !ownSenders.some((sender) => sender.config?.verified === true)
                        ? { integrationId: sandbox.id, reason: 'sandbox_sender' }
                        : null)
                )
            },
        ],
    }),
    loaders(({ values, props }) => ({
        resolvedFirstRunSender: [
            null as DefaultEmailSender | null,
            {
                resolveFirstRunSender: async (): Promise<DefaultEmailSender | null> => {
                    const projectId = values.currentProjectId
                    if (values.integrations === null) {
                        await integrationsLogic.asyncActions.loadIntegrations()
                    }
                    if (values.currentProjectId !== projectId || values.integrations === null) {
                        return null
                    }
                    if (!props.allowSandbox) {
                        return resolveDefaultEmailSender(
                            values.integrations,
                            values.currentTeam && 'workflows_config' in values.currentTeam
                                ? values.currentTeam.workflows_config?.default_email_integration_id
                                : null
                        )
                    }
                    if (
                        !values.firstRunSender &&
                        values.sandboxEmailSenderEnabled &&
                        (!values.sandboxEmailSenderProvisionResult ||
                            values.sandboxEmailSenderProvisionResult === 'failed') &&
                        !values.ownEmailIntegrations.some((sender) => sender.config?.verified === true)
                    ) {
                        await integrationsLogic.asyncActions.provisionSandboxEmailSender()
                    }
                    return values.currentProjectId === projectId ? values.firstRunSender : null
                },
            },
        ],
    })),
])
